var _markdown = "\n\n# Animations [#animations]\n\nThe Onboarding component includes various animation options and supports custom animations.\n\n## Built-in Animations [#built-in-animations]\n\n### Scroll Animation [#scroll-animation]\n\n```jsx\n<Onboarding\n  scrollAnimationDuration={500}\n  useNativeDriver={true}\n/>\n```\n\n### Dot Animation [#dot-animation]\n\n```jsx\n<Onboarding\n  dotAnimation={{\n    type: 'slide',\n    duration: 300,\n  }}\n/>\n```\n\n## Custom Animations [#custom-animations]\n\n### Fade Animation [#fade-animation]\n\n```jsx\nconst FadeView = ({ children }) => {\n  const fadeAnim = useRef(new Animated.Value(0)).current;\n\n  useEffect(() => {\n    Animated.timing(fadeAnim, {\n      toValue: 1,\n      duration: 1000,\n      useNativeDriver: true,\n    }).start();\n  }, []);\n\n  return (\n    <Animated.View style={{ opacity: fadeAnim }}>\n      {children}\n    </Animated.View>\n  );\n};\n\nconst CustomPage = () => (\n  <FadeView>\n    <Text>Welcome!</Text>\n  </FadeView>\n);\n```\n\n### Slide Animation [#slide-animation]\n\n```jsx\nconst SlideView = ({ children, direction = 'right' }) => {\n  const slideAnim = useRef(new Animated.Value(direction === 'right' ? 100 : -100)).current;\n\n  useEffect(() => {\n    Animated.spring(slideAnim, {\n      toValue: 0,\n      tension: 10,\n      friction: 8,\n      useNativeDriver: true,\n    }).start();\n  }, []);\n\n  return (\n    <Animated.View\n      style={{\n        transform: [{ translateX: slideAnim }],\n      }}\n    >\n      {children}\n    </Animated.View>\n  );\n};\n```\n\n### Scale Animation [#scale-animation]\n\n```jsx\nconst ScaleView = ({ children }) => {\n  const scaleAnim = useRef(new Animated.Value(0)).current;\n\n  useEffect(() => {\n    Animated.spring(scaleAnim, {\n      toValue: 1,\n      tension: 20,\n      friction: 7,\n      useNativeDriver: true,\n    }).start();\n  }, []);\n\n  return (\n    <Animated.View\n      style={{\n        transform: [{ scale: scaleAnim }],\n      }}\n    >\n      {children}\n    </Animated.View>\n  );\n};\n```\n\n### Sequence Animation [#sequence-animation]\n\n```jsx\nconst SequenceView = ({ children }) => {\n  const animations = {\n    slideUp: useRef(new Animated.Value(50)).current,\n    fade: useRef(new Animated.Value(0)).current,\n  };\n\n  useEffect(() => {\n    Animated.sequence([\n      Animated.timing(animations.slideUp, {\n        toValue: 0,\n        duration: 500,\n        useNativeDriver: true,\n      }),\n      Animated.timing(animations.fade, {\n        toValue: 1,\n        duration: 500,\n        useNativeDriver: true,\n      }),\n    ]).start();\n  }, []);\n\n  return (\n    <Animated.View\n      style={{\n        opacity: animations.fade,\n        transform: [{ translateY: animations.slideUp }],\n      }}\n    >\n      {children}\n    </Animated.View>\n  );\n};\n```\n\n## Implementation Examples [#implementation-examples]\n\n### Animated Page Transition [#animated-page-transition]\n\n```jsx\nconst AnimatedPage = ({ title, subtitle, image }) => {\n  const { currentPage } = useOnboarding();\n  const animations = {\n    image: useRef(new Animated.Value(0)).current,\n    title: useRef(new Animated.Value(0)).current,\n    subtitle: useRef(new Animated.Value(0)).current,\n  };\n\n  useEffect(() => {\n    Animated.stagger(200, [\n      Animated.spring(animations.image, {\n        toValue: 1,\n        tension: 10,\n        friction: 8,\n        useNativeDriver: true,\n      }),\n      Animated.spring(animations.title, {\n        toValue: 1,\n        tension: 10,\n        friction: 8,\n        useNativeDriver: true,\n      }),\n      Animated.spring(animations.subtitle, {\n        toValue: 1,\n        tension: 10,\n        friction: 8,\n        useNativeDriver: true,\n      }),\n    ]).start();\n  }, [currentPage]);\n\n  return (\n    <View style={styles.container}>\n      <Animated.Image\n        source={image}\n        style={[\n          styles.image,\n          {\n            opacity: animations.image,\n            transform: [\n              { scale: animations.image },\n            ],\n          },\n        ]}\n      />\n      <Animated.Text\n        style={[\n          styles.title,\n          {\n            opacity: animations.title,\n            transform: [\n              { translateY: animations.title.interpolate({\n                inputRange: [0, 1],\n                outputRange: [20, 0],\n              })},\n            ],\n          },\n        ]}\n      >\n        {title}\n      </Animated.Text>\n      <Animated.Text\n        style={[\n          styles.subtitle,\n          {\n            opacity: animations.subtitle,\n            transform: [\n              { translateY: animations.subtitle.interpolate({\n                inputRange: [0, 1],\n                outputRange: [20, 0],\n              })},\n            ],\n          },\n        ]}\n      >\n        {subtitle}\n      </Animated.Text>\n    </View>\n  );\n};\n```\n";
